<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #0f1115;
    --panel: #1b1e27;
    --accent: #5ee7c0;
    --accent2: #ff6b81;
    --grid-bg: #14161c;
    --grid-line: #2a2e3a;
    --cell-alive: #5ee7c0;
    --cell-alive-glow: #9dffe5;
    --text: #e6e8ee;
  }

  * { box-sizing: border-box; }

  html, body {
    height: 100%;
    margin: 0;
    background: radial-gradient(circle at 50% 0%, #1a1d27 0%, #0f1115 60%);
    color: var(--text);
    font-family: 'Segoe UI', Tahoma, Verdana, sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
  }

  h1 {
    font-size: 1.4rem;
    letter-spacing: 0.08em;
    margin: 1rem 0 0.5rem;
    color: var(--accent);
    text-shadow: 0 0 10px rgba(94, 231, 192, 0.4);
    user-select: none;
  }

  #wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
    padding: 1.2rem;
    background: var(--panel);
    border-radius: 16px;
    box-shadow: 0 10px 40px rgba(0,0,0,0.5), inset 0 0 0 1px rgba(255,255,255,0.03);
  }

  #life {
    background: var(--grid-bg);
    border-radius: 8px;
    box-shadow: 0 0 0 2px #2a2e3a, 0 0 20px rgba(94,231,192,0.08) inset;
    cursor: crosshair;
    touch-action: none;
  }

  #controls {
    display: flex;
    gap: 0.7rem;
    flex-wrap: wrap;
    justify-content: center;
  }

  button {
    background: linear-gradient(145deg, #232733, #1a1d26);
    color: var(--text);
    border: 1px solid #333849;
    padding: 0.55rem 1.1rem;
    border-radius: 10px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.15s ease;
    letter-spacing: 0.03em;
  }

  button:hover {
    border-color: var(--accent);
    color: var(--accent);
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(94,231,192,0.15);
  }

  button:active {
    transform: translateY(0px) scale(0.97);
  }

  button.on {
    background: linear-gradient(145deg, var(--accent), #38b898);
    color: #06110d;
    border-color: var(--accent);
    font-weight: 600;
  }

  #status {
    font-size: 0.8rem;
    color: #888ea3;
    letter-spacing: 0.05em;
    user-select: none;
  }

  #status span {
    color: var(--accent2);
    font-weight: 600;
  }
</style>
</head>
<body>

<h1>CONWAY'S GAME OF LIFE</h1>

<div id="wrap">
  <canvas id="life" width="500" height="500"></canvas>
  <div id="controls">
    <button id="step">⏭ Step</button>
    <button id="play">▶ Play</button>
    <button id="random">🎲 Random</button>
    <button id="clear">🧹 Clear</button>
  </div>
  <div id="status">Generation: <span id="gen">0</span> &nbsp;|&nbsp; Alive: <span id="alive">0</span></div>
</div>

<script>
(function() {
  const W = 50, H = 50; // grid cells, both >= 40
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');

  // ensure canvas has real pixel backing that matches CSS size >= 400x400
  const cssSize = 500;
  canvas.style.width = cssSize + 'px';
  canvas.style.height = cssSize + 'px';
  canvas.width = cssSize;
  canvas.height = cssSize;

  const cellW = canvas.width / W;
  const cellH = canvas.height / H;

  let grid = new Uint8Array(W * H);
  let genCount = 0;

  function idx(x, y) { return y * W + x; }

  function inBounds(x, y) {
    return x >= 0 && x < W && y >= 0 && y < H;
  }

  function get(x, y) {
    if (!inBounds(x, y)) return 0;
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (!inBounds(x, y)) return;
    grid[idx(x, y)] = v ? 1 : 0;
    draw();
  }

  function countNeighbors(x, y) {
    let n = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        n += get(x + dx, y + dy);
      }
    }
    return n;
  }

  function step() {
    const next = new Uint8Array(W * H);
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        const alive = grid[idx(x, y)];
        const n = countNeighbors(x, y);
        let newState = 0;
        if (alive) {
          newState = (n === 2 || n === 3) ? 1 : 0;
        } else {
          newState = (n === 3) ? 1 : 0;
        }
        next[idx(x, y)] = newState;
      }
    }
    grid = next;
    genCount++;
    draw();
    updateStatus();
  }

  function clearGrid() {
    grid = new Uint8Array(W * H);
    genCount = 0;
    draw();
    updateStatus();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.25 ? 1 : 0;
    }
    genCount = 0;
    draw();
    updateStatus();
  }

  function updateStatus() {
    let alive = 0;
    for (let i = 0; i < grid.length; i++) alive += grid[i];
    document.getElementById('gen').textContent = genCount;
    document.getElementById('alive').textContent = alive;
  }

  function draw() {
    ctx.fillStyle = '#14161c';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // grid lines
    ctx.strokeStyle = '#2a2e3a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= W; x++) {
      const px = Math.round(x * cellW) + 0.5;
      ctx.moveTo(px, 0);
      ctx.lineTo(px, canvas.height);
    }
    for (let y = 0; y <= H; y++) {
      const py = Math.round(y * cellH) + 0.5;
      ctx.moveTo(0, py);
      ctx.lineTo(canvas.width, py);
    }
    ctx.stroke();

    // alive cells
    for (let y = 0; y < H; y++) {
      for (let x = 0; x < W; x++) {
        if (grid[idx(x, y)]) {
          const px = x * cellW;
          const py = y * cellH;
          ctx.fillStyle = '#5ee7c0';
          ctx.shadowColor = '#9dffe5';
          ctx.shadowBlur = 6;
          ctx.fillRect(px + 1, py + 1, cellW - 2, cellH - 2);
          ctx.shadowBlur = 0;
        }
      }
    }
  }

  // expose API
  window.life = {
    w: W,
    h: H,
    get,
    set,
    step,
    clear: clearGrid
  };

  // ---------- UI wiring ----------

  const stepBtn = document.getElementById('step');
  const playBtn = document.getElementById('play');
  const randomBtn = document.getElementById('random');
  const clearBtn = document.getElementById('clear');

  let playing = false;
  let intervalId = null;
  const SPEED_MS = 120;

  function togglePlay() {
    playing = !playing;
    if (playing) {
      playBtn.textContent = '⏸ Pause';
      playBtn.classList.add('on');
      intervalId = setInterval(step, SPEED_MS);
    } else {
      playBtn.textContent = '▶ Play';
      playBtn.classList.remove('on');
      clearInterval(intervalId);
      intervalId = null;
    }
  }

  stepBtn.addEventListener('click', () => {
    step();
  });

  playBtn.addEventListener('click', togglePlay);

  randomBtn.addEventListener('click', () => {
    randomize();
  });

  clearBtn.addEventListener('click', () => {
    clearGrid();
  });

  // ---------- Mouse / touch painting ----------

  let isDragging = false;
  let paintValue = 1;
  let lastCell = null;

  function getCellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    const relX = clientX - rect.left;
    const relY = clientY - rect.top;
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = Math.floor((relX * scaleX) / cellW);
    const y = Math.floor((relY * scaleY) / cellH);
    return { x, y };
  }

  function paintAt(e) {
    const { x, y } = getCellFromEvent(e);
    if (!inBounds(x, y)) return;
    if (lastCell && lastCell.x === x && lastCell.y === y) return;
    lastCell = { x, y };
    set(x, y, paintValue);
  }

  canvas.addEventListener('mousedown', (e) => {
    isDragging = true;
    const { x, y } = getCellFromEvent(e);
    if (inBounds(x, y)) {
      paintValue = grid[idx(x, y)] ? 0 : 1;
      lastCell = null;
      set(x, y, paintValue);
      lastCell = { x, y };
    }
    e.preventDefault();
  });

  window.addEventListener('mouseup', () => {
    isDragging = false;
    lastCell = null;
  });

  canvas.addEventListener('mousemove', (e) => {
    if (isDragging) paintAt(e);
  });

  canvas.addEventListener('mouseleave', () => {
    // keep dragging state, allow re-entry, but reset lastCell so edge repaint works
  });

  // touch support
  canvas.addEventListener('touchstart', (e) => {
    isDragging = true;
    const { x, y } = getCellFromEvent(e);
    if (inBounds(x, y)) {
      paintValue = grid[idx(x, y)] ? 0 : 1;
      lastCell = null;
      set(x, y, paintValue);
      lastCell = { x, y };
    }
    e.preventDefault();
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    if (isDragging) paintAt(e);
    e.preventDefault();
  }, { passive: false });

  window.addEventListener('touchend', () => {
    isDragging = false;
    lastCell = null;
  });

  // initial draw
  draw();
  updateStatus();

})();
</script>
</body>
</html>
